function d2_assert($v,$m='API2A assertion failed'){if(!$v)throw new RuntimeException($m);}
function d2_case($name,$fn){$GLOBALS['cases'][$name]=$fn;}
function d2_error($fn,$status,$code){try{$fn();}catch(A\ApiError$e){d2_assert($e->getCode()===$status&&$e->apiCode===$code,'Wrong error '.$e->apiCode);return;}throw new RuntimeException('Expected denial');}
function d2_key($ids=null,$scopes=array('read:data'),$mode='SELECTED'){$r=$GLOBALS['keys']->create(array('name'=>'Data integration','scopes'=>$scopes,'grant_mode'=>$mode,'studies'=>$ids??array($GLOBALS['p']['definition']['study']['logical_id']),'expires_at'=>null),1,A\Authenticator::requestId());$GLOBALS['ownedKeys'][]=$r['key']['id'];$r['principal']=(new A\Authenticator())->authenticate('Bearer '.$r['secret'],A\Authenticator::requestId(),'api2a-tests');return$r;}
function d2_read($k,$params=array(),$p=null,$dict=false){return (new A\StudyDataExport())->read($k['principal'],($p??$GLOBALS['p'])['public'],$params,$dict);}
function d2_publish($long=false,$definition=null){$p=$definition!==null?pe_publish('simple',false,$definition):($long?pf_publish(null,array('verification_policy'=>'ALLOW_UNVERIFIED')):pe_publish());$GLOBALS['ownedStudies'][]=$p['definition']['study']['logical_id'];return$p;}
function d2_finish($p,$text='=UTF-8 á\nsegunda línea'){$long=($p['definition']['protocol_metadata']['enrollment_mode']??null)==='EMAIL_LONGITUDINAL';$f=$long?pf_enroll($p):pe_runtime()->handle($p['public']);$runtime=$long?pf_runtime():pe_runtime();$done=$runtime->handle($p['public'],$f['token'],pe_request($f,'submit',array('R_q1'=>$text)));d2_assert($done['view']['next_action']['kind']==='FINISHED','Fixture not completed');return array('frame'=>$f,'done'=>$done);}
function d2_http($k=null,$p=null,$params=array(),$dictionary=false,$method='GET'){$code=($p??$GLOBALS['p'])['public'];$url='http://127.0.0.1/?'.http_build_query(array_merge(array('rest_route'=>'/eipsi-external/v1/studies/'.$code.($dictionary?'/dictionary':'/data')),$params));$headers=array('Host'=>'127.0.0.1:18080');if($k!==null)$headers['Authorization']='Bearer '.$k['secret'];$r=wp_remote_request($url,array('method'=>$method,'headers'=>$headers,'timeout'=>20));d2_assert(!is_wp_error($r));return array('status'=>wp_remote_retrieve_response_code($r),'data'=>json_decode(wp_remote_retrieve_body($r),true),'body'=>wp_remote_retrieve_body($r),'headers'=>wp_remote_retrieve_headers($r));}
function d2_management($p,$partials=false){$q=new M\Query($p['definition']['study']['logical_id']);$x=new M\Exports($q);$job=$x->create(array('include_partials'=>$partials),'responses','API2_MGMT_'.bin2hex(random_bytes(8)));while(in_array($job['state'],array('PENDING','RUNNING'),true))$job=$x->step($job['id']);d2_assert($job['state']==='READY','Management export not ready');return json_decode($x->download($job['id'],'json')['content'],true)['rows'];}
function d2_normalize($rows){$rows=array_map(array(A\StudyDataExport::class,'dates'),$rows);usort($rows,static function($a,$b){return strcmp(EIPSI\StudyEngine\Contracts\Canonical::json($a),EIPSI\StudyEngine\Contracts\Canonical::json($b));});return$rows;}
