 if($random){$text=$d['elements'][0];$children=array();foreach(array('A','B')as$t){$e=$text;$e['id']='EL_RANDOM_'.$t;$e['response_key']='R_RANDOM_'.$t;$e['properties']['variable_name']='random_'.$t;$children[]=$e;}$d['elements']=array(array('id'=>'EL_RANDOM_GROUP','type'=>'randomization','response_key'=>null,'properties'=>array('label'=>'Random','mode'=>'select','count'=>1,'order'=>'random'),'options'=>array(),'children'=>$children));}
 $d=EIPSI\AssessmentEditor\Definition::validate($d);$d['flow']['pages']=array();$d['flow']['metadata_profile']=$profile;$d['flow']['save_continue']['enabled']=true;$d=EIPSI\AssessmentEditor\Definition::validate($d);EIPSI\AssessmentEditor\Repository::save($d,0);$v=$owner->publish($d['id'],1);$GLOBALS['nativeFixtures'][]=array('assessment'=>$d['id'],'version'=>$v['version_id']);
