}

function d2_parity($a,$b){$a=d2_normalize($a);$b=d2_normalize($b);if(count($a)!==count($b))throw new RuntimeException('Parity row counts '.count($a).' vs '.count($b));foreach($a as$i=>$r){$diff=array();foreach($r as$key=>$value)if(EIPSI\StudyEngine\Contracts\Canonical::json($value)!==EIPSI\StudyEngine\Contracts\Canonical::json($b[$i][$key]))$diff[]=$key;if($diff)throw new RuntimeException('Parity differs at row '.$i.': '.implode(',',$diff));}}
